import{_ as a,o as s,c as o,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Desempenho e trabalho limitado","description":"","frontmatter":{"title":"Desempenho e trabalho limitado","docId":"developer.performance","translationKey":"developer.performance","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","translationRevision":"05ab61ca49c64e95b15cb947f32042adae5820de15ca8999b2fb49b6f7aa0e93","order":110},"headers":[],"relativePath":"pt/developer/performance.md","filePath":"pt/developer/performance.md","lastUpdated":1794611623000}'),t={name:"pt/developer/performance.md"};function r(n,e,d,l,c,p){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="performance-and-bounded-work" tabindex="-1">Desempenho e trabalho limitado <a class="header-anchor" href="#performance-and-bounded-work" aria-label="Permalink to &quot;Desempenho e trabalho limitado {#performance-and-bounded-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Meça um gargalo concreto preservando contabilização de eventos e encerramento. Comece com compilação fixa, entrada determinística e perfil isolado. Leia <a href="./events.html">eventos</a> para não confundir um feed mais rápido com persistência mais confiável. Números históricos de benchmark são observações da compilação e máquina identificadas, não garantias atuais do produto.</p><h2 id="measure-the-right-boundary" tabindex="-1">Meça o limite correto <a class="header-anchor" href="#measure-the-right-boundary" aria-label="Permalink to &quot;Meça o limite correto {#measure-the-right-boundary}&quot;">​</a></h2><p>A outbox do desktop separa apresentação com perdas de respostas confiáveis. Instantâneos podem ser combinados; estouro da via confiável deve falhar visivelmente. Entrada de LIVE, trabalho de plugins, chamadas de processadores e admissão de automações têm seus próprios limites. Aumentar uma fila pode transferir pressão de memória ou latência para a próxima etapa.</p><p>O runtime do frontend expõe diagnósticos agregados em desenvolvimento ou quando compilado com <code>VITE_TIKTOOLS_DIAGNOSTICS=1</code>. Seu instantâneo inclui linhas renderizadas, percentis de intervalo entre quadros, chamadas pendentes do cliente de controle, imagens e temporizadores sob sua responsabilidade. Dados de heap JavaScript podem estar indisponíveis em determinada WebView. Páginas ocultas e visibilidade do host governam o interesse de apresentação, não a contabilização de negócio.</p><h2 id="run-a-focused-comparison" tabindex="-1">Execute uma comparação focada <a class="header-anchor" href="#run-a-focused-comparison" aria-label="Permalink to &quot;Execute uma comparação focada {#run-a-focused-comparison}&quot;">​</a></h2><ol><li>Registre revisão da compilação, plataforma, composição de eventos, imagens ativadas, aba visível e duração.</li><li>Estabeleça uma referência com os mesmos dados de teste e período de amostragem.</li><li>Altere um limite e compare vazão, latência p95/p99, descartes de fila, lacunas, memória retida e drenagem no encerramento.</li><li>Inclua um plugin ou consumidor lento e uma fila saturada; um benchmark ocioso não testa contrapressão.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence,native-tiktok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_throughput</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Inspecione requisitos de recursos antes de ativar um benchmark nativo; verificações unitárias específicas comuns não precisam de conexão real com TikTok. Use <code>crates/tiktools-core/tests/live_throughput.rs</code> e os testes da outbox do desktop como referências de implementação.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Caminhos limitados de projeção e admissão estão implementados, com contadores e relato de lacunas. O <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/services/points/queue.rs" target="_blank" rel="noreferrer">gravador ordenado atual</a> rejeita gravações saturadas antes de alterar a memória e proíbe a alternativa de gravação síncrona. Relatórios antigos de desempenho descrevem defeitos de ordenação já superados. Avalie limites de cache e recuperação de falhas pela implementação/testes atuais em vez de deduzir correção completa de uma memória de interface limitada.</p><h2 id="recover" tabindex="-1">Recupere <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Recupere {#recover}&quot;">​</a></h2><p>Se os quadros melhorarem enquanto a integridade da contabilização piorar, reverta a alteração no limite e inspecione os resultados do gravador/admissão. Se temporizadores de abas ocultas crescerem, siga a <a href="./lifecycle.html">limpeza de ciclo de vida</a>. Mantenha contagem de entrada bruta, contagem aceita e classificação de perdas no relatório. Uma lacuna pode recuperar estado de exibição; não pode reparar um efeito rejeitado ou que ficou incerto.</p>`,14)])])}const h=a(t,[["render",r]]);export{u as __pageData,h as default};
